 for a,b in [('« géométrique »',r'\fquote{géométrique}'),('« variétés »',r'\fquote{variétés}'),('« tamely ramified »',r'\fquote{tamely ramified}'),('« problème des trois points »',r'\fquote{problème des trois points}')]:
  r(a,b,'quotation '+a,why='Ordinary double quotation marks.')
 r('sera,\npar exemple,','sera\npar exemple,','Cohen-ring parenthesis punctuation',why='No comma follows sera; the comma after exemple is printed.')
